<?php
declare(strict_types=1);
if (PHP_SAPI!=='cli') exit(1);
putenv('APP_ENV=local');putenv('LUMS_DB_DSN=sqlite::memory:');putenv('LUMS_SESSION_PATH='.sys_get_temp_dir().'/lums-room-test-'.bin2hex(random_bytes(8)));
require dirname(__DIR__).'/src/bootstrap.php'; initialize_database(db(),true);start_lums_session();
$checks=0;$expect=static function(bool $ok,string $message) use (&$checks) {if(!$ok)throw new RuntimeException($message);$checks++;echo "PASS: $message\n";};
$admin=(int)db()->query("SELECT id FROM users WHERE role='admin'")->fetchColumn();$lecturer=(int)db()->query("SELECT id FROM users WHERE role='lecturer'")->fetchColumn();
$now=utc_now();$token=bin2hex(random_bytes(16));
db()->prepare("INSERT INTO rooms(code,name,building,floor,capacity,status,qr_token,created_at,updated_at) VALUES ('QR-TEST','ห้องทดสอบสมมติ','อาคารทดสอบ','1',2,'available',?,?,?)")->execute([$token,$now,$now]);$room=(int)db()->lastInsertId();
$token2=bin2hex(random_bytes(16));db()->prepare("INSERT INTO rooms(code,name,building,floor,capacity,status,qr_token,created_at,updated_at) VALUES ('QR-TEST2','ห้องสอง','อาคารทดสอบ','1',2,'available',?,?,?)")->execute([$token2,$now,$now]);$room2=(int)db()->lastInsertId();
$expect(public_room('bad')===null && public_room(str_repeat('f',32))===null,'Invalid and unknown room tokens reveal nothing');
$expect((int)public_room($token)['id']===$room,'Stable room token resolves room');
